 assemblyDeleting=true;const button=$('#assembly-delete');if(button)button.disabled=true;
 try{const before=captureRemovalView(stage,project);remember();project.instances=project.instances.filter(i=>i.id!==id);if(selected===id)selected=null;++loadEpoch;removeRenderedInstances(stage,[id]);markDirty();updateAssemblyObjects();assemblyRemovalViews=[before,captureRemovalView(stage,project)];notify('已从装配移除：'+instance.name+' · ⌘Z 可撤销');}
